const p=load("page");const body=p.text.split("<content>\n")[1].split("\n</content>")[0]; store("body",body);
const lines=body.split("\n");let section="";const updates=[];
for(const line of lines){if(line.startsWith("**Cut immediately"))section="cut";if(line.startsWith("## "))section=line;if(line.startsWith("- [ ] ") && section!=="cut" && !line.includes("Rehearse a complete") && !line.includes("One complete demo"))updates.push({old_str:line,new_str:line.replace("- [ ]","- [x]")});}
store("updates",updates);text({checkboxes:updates.length,items:updates.map(x=>x.new_str)});
